import React from 'react';
import { useParams } from 'react-router-dom';
import { moviesData } from '../data/moviesData';

function MovieDetail() {
  const { id } = useParams();
  const movie = moviesData[id] || Object.values(moviesData)[0];

  if (!movie) return <div className="text-white text-center py-20">영화를 찾을 수 없습니다.</div>;

  return (
    <div className="w-full min-h-screen bg-[#1c1c1e] text-white font-sans relative pb-20">
      
      {/* 💡 1. 캡처 화면과 동일한 상단 백드롭(배경) 및 어두운 그라데이션 오버레이 */}
      <div className="absolute top-0 left-0 w-full h-[500px] overflow-hidden z-0">
        <img 
          src={process.env.PUBLIC_URL + movie.poster} 
          alt="backdrop" 
          className="w-full h-full object-cover opacity-40 blur-md scale-105"
        />
        <div className="absolute inset-0 bg-gradient-to-b from-black/50 via-[#1c1c1e]/80 to-[#1c1c1e]"></div>
      </div>

      {/* 컨텐츠 메인 Wrapper */}
      <div className="relative z-10 max-w-5xl mx-auto pt-28 px-6">
        
        {/* 영화 타이틀 및 메타 정보 (캡처 화면 형태) */}
        <div className="mb-8">
          <h1 className="text-4xl md:text-5xl font-black tracking-tight text-white mb-3 drop-shadow-lg">
            {movie.title}
          </h1>
          <p className="text-zinc-300 text-sm md:text-base font-bold mb-4">
            {movie.year} · {movie.age} · {movie.duration} · Language: {movie.language}
          </p>
          
          {/* 장르 뱃지 (캡처 형태 유지) */}
          <div className="flex flex-wrap gap-2">
            {movie.genres?.map((genre, idx) => (
              <span key={idx} className="bg-zinc-800/80 backdrop-blur text-zinc-200 text-xs font-bold px-4 py-1.5 rounded-full border border-white/10 shadow-sm">
                {genre}
              </span>
            ))}
          </div>
        </div>

        {/* 💡 2. 캡처 화면과 동일한 관람객 평점 / 예매율 / 누적관객수 통계 바 */}
        <div className="w-full bg-zinc-900/85 backdrop-blur-md rounded-2xl border border-white/10 py-6 px-8 grid grid-cols-3 text-center mb-12 shadow-2xl">
          <div className="border-r border-white/10">
            <span className="text-xs font-bold text-zinc-400 block mb-1">실관람 평점</span>
            <span className="text-2xl md:text-3xl font-black text-white">
              {movie.rating || '9.5'}
            </span>
          </div>
          <div className="border-r border-white/10">
            <span className="text-xs font-bold text-zinc-400 block mb-1">예매율</span>
            <span className="text-2xl md:text-3xl font-black text-purple-400">
              1위 <span className="text-xs text-zinc-400 font-normal">(15.4%)</span>
            </span>
          </div>
          <div>
            <span className="text-xs font-bold text-zinc-400 block mb-1">누적관객수</span>
            <span className="text-xl md:text-2xl font-black text-white">
              8,199,271 <span className="text-xs font-normal text-zinc-400">명</span>
            </span>
          </div>
        </div>

        {/* 💡 3. 중단 상세 정보 영역 (포스터 + 우측 텍스트 카드: 캡처 형태 완벽 복원 + 글씨만 큼직하게 키움) */}
        <div className="flex flex-col md:flex-row gap-10 items-start mb-16">
          
          {/* 좌측 포스터 */}
          <div className="w-full md:w-4/12 flex-shrink-0">
            <div className="w-full aspect-[3/4] rounded-2xl overflow-hidden shadow-2xl bg-zinc-800 border border-white/10">
              <img 
                src={process.env.PUBLIC_URL + movie.poster} 
                alt={movie.title} 
                className="w-full h-full object-cover" 
              />
            </div>
          </div>

          {/* 우측 텍스트 정보 (등장인물, 감독, 줄거리 - 캡처 구조 + 시원한 폰트 크기) */}
          <div className="w-full md:w-8/12 space-y-6 bg-zinc-900/60 p-8 md:p-10 rounded-3xl border border-white/10 backdrop-blur-md shadow-2xl">
            
            {/* 등장인물 */}
            <div>
              <span className="text-xs font-black uppercase tracking-widest text-purple-400 block mb-1.5">
                등장인물 :
              </span>
              <p className="text-base md:text-lg font-bold text-zinc-100">
                {movie.voiceCast || movie.casts || "마이돈 존스턴, 인디 네버레티, 쿠퍼 플린슨, 메간 로리스"}
              </p>
            </div>

            {/* 감독 */}
            <div>
              <span className="text-xs font-black uppercase tracking-widest text-purple-400 block mb-1.5">
                감독 :
              </span>
              <p className="text-base md:text-lg font-bold text-zinc-100">
                {movie.director}
              </p>
            </div>

            {/* 줄거리 (가독성 좋게 글씨 크기와 줄 간격 확대) */}
            <div>
              <span className="text-xs font-black uppercase tracking-widest text-purple-400 block mb-2">
                줄거리 :
              </span>
              <p className="text-base md:text-lg text-zinc-200 font-normal leading-relaxed tracking-wide text-justify">
                {movie.synopsis}
              </p>
            </div>

            {/* 예매하기 버튼 */}
            <div className="pt-4">
              <button className="w-full py-4 rounded-xl bg-[#503396] text-white font-black text-base hover:bg-[#3f2777] transition shadow-lg tracking-wide border border-purple-400/30">
                예매하기
              </button>
            </div>

          </div>

        </div>

        {/* 하단 갤러리 섹션 */}
        {movie.gallery && movie.gallery.length > 0 && (
          <div>
            <h3 className="text-sm font-black tracking-widest uppercase text-zinc-400 mb-6 text-center">
              G A L L E R Y
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {movie.gallery.map((imgSrc, idx) => (
                <div key={idx} className="rounded-2xl overflow-hidden bg-zinc-800 aspect-video border border-white/10 shadow-lg">
                  <img 
                    src={process.env.PUBLIC_URL + imgSrc} 
                    alt={`gallery-${idx}`} 
                    className="w-full h-full object-cover hover:scale-105 transition duration-500" 
                  />
                </div>
              ))}
            </div>
          </div>
        )}

      </div>

    </div>
  );
}

export default MovieDetail;
